#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    // The program expects an even number of arguments (pairs of vertices).
    if ((argc - 1) % 2 != 0) {
        puts("INVALID_INPUT");
        return 0;
    }

    // Graph with at most 8 vertices (0..7).
    int adj[8][8] = {{0}};
    for (int i = 1; i + 1 < argc; i += 2) {
        char *endptr;
        long u = strtol(argv[i], &endptr, 10);
        if (*endptr != '\0' || u < 0 || u >= 8) {
            puts("INVALID_INPUT");
            return 0;
        }
        long v = strtol(argv[i + 1], &endptr, 10);
        if (*endptr != '\0' || v < 0 || v >= 8) {
            puts("INVALID_INPUT");
            return 0;
        }
        adj[u][v] = 1;
        adj[v][u] = 1;
    }

    int visited[8] = {0};
    int component = 0;
    for (int start = 0; start < 8; ++start) {
        if (visited[start])
            continue;
        // BFS to collect the connected component.
        int queue[8];
        int qhead = 0, qtail = 0;
        int comp_vertices[8];
        int comp_sz = 0;

        queue[qtail++] = start;
        visited[start] = 1;
        while (qhead < qtail) {
            int v = queue[qhead++];
            comp_vertices[comp_sz++] = v;
            for (int nb = 0; nb < 8; ++nb) {
                if (adj[v][nb] && !visited[nb]) {
                    visited[nb] = 1;
                    queue[qtail++] = nb;
                }
            }
        }

        // Output the component.
        printf("%d: {", component);
        for (int i = 0; i < comp_sz; ++i) {
            if (i)
                putchar(',');
            printf("%d", comp_vertices[i]);
        }
        puts("}");
        component++;
    }
    return 0;
}
